  f = f * f * (3.0 - 2.0 * f);
  return mix(mix(fx_hash2(i), fx_hash2(i + vec2f(1.0, 0.0)), f.x),
    mix(fx_hash2(i + vec2f(0.0, 1.0)), fx_hash2(i + vec2f(1.0, 1.0)), f.x), f.y);
